        for idx, (txt, answer, sk) in enumerate(items, 1):
            # Create high quality 4-choice options
            opts = [
                ("A", answer, 1.0, True),
                ("B", f"Opposite of {sk.lower()}", 0.0, False),
                ("C", f"Unrelated trivial concept in {topic}", 0.0, False),
                ("D", "None of the above", 0.0, False)
            ]
